# compute_basis_mpi.R
# Compute Dynamic Ensemble Basis MPI (mean and median)

# Helper function to extract exactly the fundamental cycle basis (the chord cycles)
# generated by a specific Hamiltonian path 'perm' on a graph with 'T_val' nodes.
extract_basis_cycles <- function(T_val, perm) {
  cycles <- list()
  
  # 1. Back edge cycles (Contiguous subsegments closed by a back-edge)
  for (i in 1:(T_val - 1)) {
    for (j in (i + 1):T_val) {
      cyc <- perm[i:j]
      cycles[[length(cycles) + 1]] <- cyc
    }
  }
  
  # 2. Forward edge 2-cycles (Skip-edges closed by a back-edge)
  if (T_val >= 3) {
    for (i in 1:(T_val - 2)) {
      for (j in (i + 2):T_val) {
        cyc <- c(perm[i], perm[j])
        cycles[[length(cycles) + 1]] <- cyc
      }
    }
  }
  
  return(cycles)
}

library(Rcpp)
    sourceCpp("../function_scripts/rcpp_basis.cpp")

# The main function that samples Hamiltonian paths and computes the Basis MPI.
# Z is the cost matrix, Q is the quantity matrix.
eval_basis_cycles_for_Z <- function(Z, Q, tol = 1e-4, max_iter = 5000, burn_in = 1000, use_rcpp = FALSE) {
  if (use_rcpp) {
    return(eval_basis_cycles_for_Z_cpp(Z, Q, max_iter, burn_in))
  }
  t_val <- nrow(Z)
  if(t_val < 2) return(rep(NA, 7))
  
  set.seed(2026) # Set seed for reproducibility
  
  # Helper to compute the exact combinatorial frequency of a cycle of length k.
  # This serves as our inverse-probability weight to ensure an unbiased estimator.
  get_weight <- function(n, k) {
    if (k == 2) {
      return(1) # 2-cycles appear in every single basis
    } else {
      # product of n, n-1, ..., n-k+2
      num <- prod((n - k + 2):n)
      return(num / k)
    }
  }
  
  cumulative_U <- 0
  cumulative_W <- 0
  n_valid <- 0
  stable_count <- 0
  
  # Tracking arrays
  U_history <- numeric(max_iter)
  W_history <- numeric(max_iter)
  rolling_ratios <- numeric(max_iter)
  
  # Pre-allocate arrays for cycle MPIs, weights, and parent path indices
  allocated_size <- 50000 
  all_cycle_mpis <- numeric(allocated_size)
  all_cycle_weights <- numeric(allocated_size)
  all_cycle_path_idx <- integer(allocated_size)
  total_cycle_count <- 0
  
  attempt <- 1
  while (attempt <= max_iter) {
    perm <- sample(1:t_val)
    
    basis_cycles <- extract_basis_cycles(t_val, perm)
    
    U_p <- 0
    W_p <- 0
    has_valid <- FALSE
    
    for(c in basis_cycles) {
      k <- length(c)
      violation <- TRUE
      cost_sum <- 0
      budget_sum <- 0
      
      for(idx in 1:k) {
        u <- c[idx]
        v <- c[ifelse(idx == k, 1, idx + 1)]
        
        # Check strict preference condition and filter zero-cost padding edges
        # (degenerate cycles containing identical bundles) that artificially inflate length.
        if(Z[u, u] < Z[u, v] || all(Q[u,] == Q[v,])) {
          violation <- FALSE
          break
        }
        cost_sum <- cost_sum + (Z[u, u] - Z[u, v])
        budget_sum <- budget_sum + Z[u, u]
      }
      
      if(violation && cost_sum > 1e-7) {
        mpi_val <- cost_sum / budget_sum
        w <- get_weight(t_val, k)
        
        # Apply the frequency-adjusted ratio estimator logic
        U_p <- U_p + mpi_val * w
        W_p <- W_p + w
        has_valid <- TRUE
        
        total_cycle_count <- total_cycle_count + 1
        if (total_cycle_count > length(all_cycle_mpis)) {
          length(all_cycle_mpis) <- length(all_cycle_mpis) * 2
          length(all_cycle_weights) <- length(all_cycle_weights) * 2
          length(all_cycle_path_idx) <- length(all_cycle_path_idx) * 2
        }
        all_cycle_mpis[total_cycle_count] <- mpi_val
        all_cycle_weights[total_cycle_count] <- w
        all_cycle_path_idx[total_cycle_count] <- n_valid + 1
      }
    }
    
    # If the path actually generated violating cycles
    if(has_valid) {
      n_valid <- n_valid + 1
      cumulative_U <- cumulative_U + U_p
      cumulative_W <- cumulative_W + W_p
      
      U_history[n_valid] <- U_p
      W_history[n_valid] <- W_p
      
      current_ratio <- cumulative_U / cumulative_W
      rolling_ratios[n_valid] <- current_ratio
      
      # Early convergence logic
      if (n_valid > burn_in) {
        last_ratio <- rolling_ratios[n_valid - 1]
        
        if (abs(current_ratio - last_ratio) < 1e-3) {
          stable_count <- stable_count + 1
        } else {
          stable_count <- 0
        }
        
        # Stop if rolling ratio is stable for 200 iterations
        if (stable_count >= 200) {
          break
        }
      }
    }
    attempt <- attempt + 1
  }
  
  if(n_valid == 0 || cumulative_W == 0) return(c(NA, NA, NA, NA, NA, NA, NA))
  
  # Recalculate the maximum bias bound on the final ensemble
  mu_U <- mean(U_history[1:n_valid])
  mu_W <- mean(W_history[1:n_valid])
  theta <- mu_U / mu_W
  R_history <- U_history[1:n_valid] - theta * W_history[1:n_valid]
  sig_R <- sd(R_history)
  sig_W <- sd(W_history[1:n_valid])
  w_min <- min(W_history[1:n_valid])
  w_max <- max(W_history[1:n_valid])
  
  # Calculate mean bias bound
  max_bias_bound <- (sig_R * sig_W) / (mu_W * w_min * n_valid)
  if(is.na(max_bias_bound) || is.infinite(max_bias_bound)) max_bias_bound <- 0
  max_bias_bound <- min(1.0, max_bias_bound)
  
  # Frequency-adjusted ensemble mean
  final_ratio <- cumulative_U / cumulative_W
  
  # Midpoint weighted median
  valid_mpis <- all_cycle_mpis[1:total_cycle_count]
  valid_weights <- all_cycle_weights[1:total_cycle_count]
  valid_path_idx <- all_cycle_path_idx[1:total_cycle_count]
  
  # Sort MPIs and weights
  sort_idx <- order(valid_mpis)
  sorted_mpis <- valid_mpis[sort_idx]
  sorted_weights <- valid_weights[sort_idx]
  sorted_path_idx <- valid_path_idx[sort_idx]
  
  total_weight <- sum(sorted_weights)
  target_weight <- total_weight / 2.0
  cum_weights <- cumsum(sorted_weights)
  
  idx_lower <- which(cum_weights >= target_weight)[1]
  m_lower <- sorted_mpis[idx_lower]
  if (cum_weights[idx_lower] > target_weight || idx_lower == length(sorted_mpis)) {
    m_upper <- m_lower
  } else {
    m_upper <- sorted_mpis[idx_lower + 1]
  }
  weighted_median <- 0.5 * (m_lower + m_upper)
  
  # Calculate empirical sample delta gap isolating the median
  delta_sample <- 0.0
  if (total_weight > 0) {
    cdf_at_med <- sum(valid_weights[valid_mpis <= weighted_median]) / total_weight
    lt_idx <- which(valid_mpis < weighted_median - 1e-12)
    cdf_prev <- if (length(lt_idx) > 0) sum(valid_weights[lt_idx]) / total_weight else 0.0
    upper_gap <- cdf_at_med - 0.50
    lower_gap <- 0.50 - cdf_prev
    if (upper_gap > 0 && lower_gap > 0) {
      delta_sample <- min(upper_gap, lower_gap)
    }
  }
  
  # Calculate median bias bound
  median_bias_bound <- 1.0
  if(delta_sample > 0 && w_max > 0) {
    median_bias_bound <- min(1.0, 4.0 * exp(- (2.0 * n_valid * delta_sample^2 * w_min^2) / (w_max^2)))
  }
  
  # Bootstrap bias estimation
  
  B <- 1000
  boot_means <- numeric(B)
  boot_medians <- numeric(B)
  
  for (b in 1:B) {
    # Bootstrap the Mean MPI by resampling Hamiltonian paths (U_history, W_history)
    b_idx_paths <- sample(1:n_valid, n_valid, replace = TRUE)
    boot_means[b] <- sum(U_history[b_idx_paths]) / sum(W_history[b_idx_paths])
    
    # Bootstrap Median MPI over cycles in the resampled H-path bases
    path_counts <- tabulate(b_idx_paths, nbins = n_valid)
    boot_weights <- sorted_weights * path_counts[sorted_path_idx]
    boot_total_weight <- sum(boot_weights)
    b_med <- weighted_median
    if (boot_total_weight > 0) {
      b_target <- boot_total_weight / 2.0
      b_cum <- cumsum(boot_weights)
      b_idx_lower <- which(b_cum >= b_target)[1]
      b_lower <- sorted_mpis[b_idx_lower]
      if (b_cum[b_idx_lower] > b_target || b_idx_lower == length(sorted_mpis)) {
        b_upper <- b_lower
      } else {
        active_after <- which(boot_weights[(b_idx_lower + 1):length(boot_weights)] > 0)
        if (length(active_after) > 0) {
          b_upper <- sorted_mpis[b_idx_lower + active_after[1]]
        } else {
          b_upper <- b_lower
        }
      }
      b_med <- 0.5 * (b_lower + b_upper)
    }
    boot_medians[b] <- b_med
  }
  
  empirical_mean_bias <- mean(boot_means) - final_ratio
  empirical_median_bias <- mean(boot_medians) - weighted_median
  
  iterations_completed <- if (attempt <= max_iter) attempt else max_iter
  return(c(final_ratio, weighted_median, max_bias_bound, median_bias_bound, iterations_completed, empirical_mean_bias, empirical_median_bias))
}
